contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address callee, bytes memory data) public {
        bool firstOk;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstOk = false; } else { firstOk = true; }

        bool secondOk;
        c.forward(callee, data); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondOk = false; } else { secondOk = true; }

        assert(!firstOk || secondOk);
    }

    receive() external payable {}
}

